import { describe, expect, it } from 'vitest';
import { decodeNativeHistory } from './nativeHistory';
// Generated by NativeHistoryCodec from a synthetic canonical window, never user history.
const fixture = Uint8Array.from(
  atob(
    '',
  ),
  (c) => c.charCodeAt(0),
).buffer;

describe('native history wire contract', () => {
  it('reads the native schema, offsets, tick precision, Unicode, decimals and repeated values', () => {
    const decoded = decodeNativeHistory(fixture) as {
      generatedAt: string;
      latestSequence: number;
      history: { body: string; createdAt: string; updatedAt: string }[];
      quickSettings: { configOptions: Record<string, unknown>[] };
    };
    expect(decoded.generatedAt).toBe('2026-11-15T07:04:03.1234567+02:00');
    expect(decoded.latestSequence).toBe(Number('9223372036854775807'));
    expect(decoded.history[0]).toMatchObject({
      body: 'Grüße 🦊 東京',
      updatedAt: '2026-11-15T05:04:03.1234567+00:00',
    });
    expect(decoded.history[1]).toMatchObject({
      createdAt: '0001-01-01T00:00:00+00:00',
      updatedAt: '9999-12-31T23:59:59.9999999+00:00',
    });
    expect(decoded.quickSettings.configOptions[0]).toMatchObject({
      fraction: 1.25,
      list: [null, false, '東京'],
    });
    expect(Object.getPrototypeOf(decoded.quickSettings.configOptions[0])).toBe(Object.prototype);
    expect(Object.hasOwn(decoded.quickSettings.configOptions[0] ?? {}, '__proto__')).toBe(true);
    expect(({} as Record<string, unknown>)['safe']).toBeUndefined();
  });
  it('preserves opaque numbers with JSON semantics beyond decimal precision', () => {
    const packet = (text: string): ArrayBuffer => {
      const number = new TextEncoder().encode(text);
      return new Uint8Array([65, 67, 72, 49, 16, 7, number.length, ...number]).buffer;
    };
    expect(decodeNativeHistory(packet('1e-40'))).toBe(1e-40);
    expect(Object.is(decodeNativeHistory(packet('-0')), -0)).toBe(true);
    expect(decodeNativeHistory(packet('123456789012345678901234567890123456789'))).toBe(
      JSON.parse('123456789012345678901234567890123456789'),
    );
    expect(() => decodeNativeHistory(packet('NaN'))).toThrow();
  });
  it('bounds repeated-string expansion before worker-to-UI cloning', () => {
    const repeated = 700;
    const packet = new Uint8Array(4 + 1 + 2 + 1 + 3 + 65536 + repeated * 2);
    packet.set([65, 67, 72, 49, 11, 189, 5, 7, 128, 128, 4]);
    packet.fill(120, 11, 11 + 65536);
    for (let i = 0; i < repeated; i++) packet.set([8, 0], 11 + 65536 + i * 2);
    expect(() => decodeNativeHistory(packet.buffer)).toThrow('decoded size limit');
  });
  it('rejects every truncated prefix, invalid references and trailing data', () => {
    for (let n = 0; n < fixture.byteLength; n++)
      expect(() => decodeNativeHistory(fixture.slice(0, n))).toThrow();
    const trailing = new Uint8Array(fixture.byteLength + 1);
    trailing.set(new Uint8Array(fixture));
    expect(() => decodeNativeHistory(trailing.buffer)).toThrow();
    expect(() => decodeNativeHistory(new Uint8Array([65, 67, 72, 49, 8, 0]).buffer)).toThrow();
    expect(() => decodeNativeHistory(new Uint8Array([65, 67, 72, 49, 14, 0]).buffer)).toThrow();
  });
});
